CREATE TABLE proposals (id BIGINT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,description TEXT NOT NULL,bairro VARCHAR(255),tipo VARCHAR(100),location VARCHAR(255),status VARCHAR(50),author_id BIGINT NOT NULL,emoji VARCHAR(50),photo VARCHAR(500),created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_proposals_author FOREIGN KEY(author_id) REFERENCES users(id),INDEX idx_proposals_status(status),INDEX idx_proposals_author(author_id));
